  "Reference values shown across the app — they don't block trade entry automatically. Synced to your account.": "قيم مرجعية تظهر في جميع أنحاء التطبيق — لا تمنع دخول الصفقة تلقائيًا. تتم مزامنتها مع حسابك.",
