  "These actions are irreversible. Use them to reset your account to a clean state, e.g. after testing with demo data.": "هذه الإجراءات لا رجعة فيها. استخدمها لإعادة ضبط حسابك إلى حالة نظيفة، مثلًا بعد الاختبار ببيانات تجريبية.",
  "Clear all trades & import history": "مسح جميع الصفقات وسجل الاستيراد",
  "Permanently deletes every trade, rule break, review, and import batch. Opportunities and settings are kept.": "يحذف نهائيًا كل صفقة ومخالفة قاعدة ومراجعة ودفعة استيراد. يتم الاحتفاظ بالفرص والإعدادات.",
