  "icon next to labels throughout the app for field-level guidance without leaving the page.": "بجانب التسميات في جميع أنحاء التطبيق للحصول على إرشادات مستوى الحقل دون مغادرة الصفحة.",
  "Getting started": "البدء",
  "The Plan → Execute → Analyze loop": "حلقة التخطيط ← التنفيذ ← التحليل",
  "Trade OS is built around one workflow: plan an idea, execute and journal it, then analyze what actually works. Five steps to get fully set up.": "بُني Trade OS حول سير عمل واحد: خطط لفكرة، نفذها وسجلها، ثم حلل ما ينجح فعلًا. خمس خطوات للإعداد الكامل.",
  "Welcome to Trade OS": "مرحبًا بك في Trade OS",
  "Trade OS follows a simple loop: Plan your trades, Execute them, then Analyze your edge.": "يتبع Trade OS حلقة بسيطة: خطط لصفقاتك، نفذها، ثم حلل ميزتك.",
