  "Add a Watchlist opportunity and tag your context confirmations.": "أضف فرصة إلى قائمة المراقبة وسجّل تأكيدات السياق الخاصة بك.",
  "Record the trade in your Journal with entry/exit and rule breaks.": "سجّل الصفقة في سجلك مع الدخول/الخروج ومخالفات القواعد.",
