  "Trade OS follows a simple loop: Plan your trades, Execute them, then Analyze your edge.": "Trade OS sigue un ciclo simple: planifica tus operaciones, ejecútalas y analiza tu ventaja.",
  "Trade OS is built around one workflow: plan an idea, execute and journal it, then analyze what actually works. Five steps to get fully set up.": "Trade OS gira en torno a un flujo: planificar una idea, ejecutarla y registrarla, y analizar qué funciona. Cinco pasos para configurarlo todo.",
