  "Trade OS follows a simple loop: Plan your trades, Execute them, then Analyze your edge.": "Trade OS suit une boucle simple : planifiez vos trades, exécutez-les, puis analysez votre edge.",
  "Trade OS is built around one workflow: plan an idea, execute and journal it, then analyze what actually works. Five steps to get fully set up.": "Trade OS repose sur un flux unique : planifier une idée, l'exécuter et la consigner, puis analyser ce qui fonctionne. Cinq étapes pour tout configurer.",
