  "Supports MT5 \"Trade History Report\" Excel exports, MT4 HTML statements, MT5 XML exports, TradingView \"List of Trades\" CSVs, Binance position history, Bybit closed P&L, and generic CSV files": "MT5 \"Trade History Report\" Excel dışa aktarımları, MT4 HTML ekstreleri, MT5 XML dışa aktarımları, TradingView \"List of Trades\" CSV'leri, Binance pozisyon geçmişi, Bybit kapalı K/Z ve genel CSV dosyalarını destekler",
  "Sydney": "Sidney",
