  "These actions are irreversible. Use them to reset your account to a clean state, e.g. after testing with demo data.": "Bu işlemler geri alınamaz. Örneğin demo verilerle denemeden sonra hesabınızı temiz duruma döndürmek için kullanın.",
  "They are auto-deselected but you can re-check them to force re-import.": "Otomatik olarak seçimleri kaldırılır, ancak yeniden içe aktarmak için tekrar işaretleyebilirsiniz.",
