  "To hour (UTC)": "Bitiş saati (UTC)",
  "Toggle signals that are currently active in the market.": "Şu anda piyasada aktif olan sinyalleri işaretleyin.",
  "Toggle theme": "Temayı değiştir",
  "Tokyo": "Tokyo",
