  "Total Return": "Toplam getiri",
  "Trade Data": "İşlem verileri",
  "Trade Journal": "İşlem günlüğü",
  "Trade OS follows a simple loop: Plan your trades, Execute them, then Analyze your edge.": "Trade OS basit bir döngü izler: İşlemlerinizi planlayın, uygulayın, sonra avantajınızı analiz edin.",
  "Trade OS is built around one workflow: plan an idea, execute and journal it, then analyze what actually works. Five steps to get fully set up.": "Trade OS tek bir iş akışına dayanır: fikri planla, uygula ve günlüğe kaydet, sonra neyin işe yaradığını analiz et. Tam kurulum için beş adım.",
  "Trade created": "İşlem oluşturuldu",
