  "Trade notes, observations...": "İşlem notları, gözlemler...",
  "Trade updated": "İşlem güncellendi",
  "Trades you log or import will appear here once they fall within the selected period.": "Kaydettiğiniz veya içe aktardığınız işlemler, seçilen döneme girdiklerinde burada görünür.",
  "Trading Accounts": "İşlem hesapları",
