  "Upload OHLC CSV": "OHLC CSV yükle",
  "Upload OHLC candles from any platform and test rule-based strategies before risking capital.": "Herhangi bir platformdan OHLC mumları yükleyin ve sermaye riske atmadan kural tabanlı stratejileri test edin.",
  "Upload or select a price series, configure a strategy, and press Run Backtest.": "Bir fiyat serisi yükleyin veya seçin, stratejiyi yapılandırın ve Backtest Çalıştır'a basın.",
  "Valid Conditions": "Geçerli koşullar",
  "Valid Conditions (one per line)": "Geçerli koşullar (her satıra bir tane)",
