  "h": "sa",
  "icon next to labels throughout the app for field-level guidance without leaving the page.": "sayfadan ayrılmadan alan düzeyinde yardım için uygulama genelinde etiketlerin yanındaki simge.",
  "import from MetaTrader": "MetaTrader'dan içe aktarın",
