  "Trade OS follows a simple loop: Plan your trades, Execute them, then Analyze your edge.": "O Trade OS segue um ciclo simples: planeje suas operações, execute-as e analise sua vantagem.",
  "Trade OS is built around one workflow: plan an idea, execute and journal it, then analyze what actually works. Five steps to get fully set up.": "O Trade OS gira em torno de um fluxo: planejar uma ideia, executar e registrar, depois analisar o que funciona. Cinco passos para configurar tudo.",
