  "Number of context tags currently enabled for this opportunity. Higher confirmation counts correlate with higher-probability setups.": "Número de etiquetas de contexto ativas nesta oportunidade. Mais confirmações se correlacionam com setups de maior probabilidade.",
  "Onboarding banner": "Banner de boas-vindas",
  "Open Settings → General and set your risk per trade, max daily loss, and minimum R. These become reference benchmarks across the whole app.": "Abra Configurações → Geral e defina risco por operação, perda diária máxima e R mínimo. Eles viram referências em todo o app.",
  "Opportunity detail tabs": "Abas de detalhe da oportunidade",
  "Overview — bias, session, status, notes, and one-click status buttons (Taken / Skipped / Not Formed)": "Visão Geral — viés, sessão, status, notas e botões de status de um clique (Realizada / Pulada / Não formada)",
  "Overview — read-only summary: entry/exit, size, fees, session, timestamps, notes, active context, rule breaks, and delete": "Visão Geral — resumo somente leitura: entrada/saída, tamanho, taxas, sessão, horários, notas, contexto ativo, infrações e exclusão",
  "Panels on this page": "Painéis desta página",
  "Percentage of trades that closed with P&L > 0. Aim for consistency above 50%, but pair it with profit factor — a 45% win rate with 2R winners still has positive expectancy.": "Percentual de operações fechadas com P&L > 0. Busque consistência acima de 50%, mas leia junto com o fator de lucro — 45% de acerto com ganhos de 2R ainda tem expectativa positiva.",
  "Pick a setup name from your Playbook when creating a Watchlist opportunity — the same name then groups trades in Edge Lab so you can see which playbooks are actually delivering.": "Escolha um nome de setup do Playbook ao criar uma oportunidade — o mesmo nome agrupa operações no Edge Lab para ver quais playbooks realmente entregam.",
  "Plan a new trading idea": "Planeje uma nova ideia de trading",
  "Plan an opportunity": "Planeje uma oportunidade",
  "Plan and track every trade idea before you pull the trigger.": "Planeje e acompanhe cada ideia antes de puxar o gatilho.",
  "Plan high-quality setups": "Planejar setups de alta qualidade",
  "Planned → Watching → Taken (once linked to a trade) or Skipped / Not Formed. Update status from the Overview tab as the idea develops.": "Planejada → Em observação → Realizada (ao vincular a uma operação) ou Pulada / Não formada. Atualize o status pela aba Visão Geral conforme a ideia evolui.",
  "Pre-market and post-market SOP checklists.": "Checklists SOP de pré e pós-mercado.",
  "Presets: Today, This Week, This Month, QTD, YTD, All Time, or a custom range": "Predefinições: Hoje, Esta semana, Este mês, QTD, YTD, Todo o período ou intervalo personalizado",
  "Preview and import": "Pré-visualizar e importar",
  "Purpose": "Propósito",
  "QTD": "QTD",
  "Quarter to Date": "Trimestre até agora",
  "Quick Actions & Active Playbooks": "Ações rápidas e playbooks ativos",
  "R is risk-adjusted return — how many multiples of your initial risk you made or lost. A +2R trade means you made twice your risk regardless of dollar size. Target an average R above the minimum you set in Settings.": "R é o retorno ajustado ao risco — quantos múltiplos do seu risco inicial você ganhou ou perdeu. +2R significa o dobro do risco, qualquer que seja o tamanho em dólares. Busque um R médio acima do mínimo definido em Configurações.",
  "R-Multiple": "Múltiplo R",
  "Read win rate and profit factor together — a high win rate with profit factor below 1.0 means winners are too small relative to losers. Use the Session Analysis and Hour Analysis panels to find your best trading windows.": "Leia taxa de acerto e fator de lucro juntos — taxa alta com fator abaixo de 1,0 significa ganhos pequenos demais frente às perdas. Use os painéis de sessão e hora para achar suas melhores janelas.",
  "Record a new trade in your journal": "Registre uma nova operação no seu diário",
  "Record entries in the Journal, either manually or via import. Tag context signals and rule breaks on each trade to build a real dataset.": "Registre entradas no Diário, manualmente ou por importação. Marque sinais de contexto e infrações em cada operação para construir um dataset real.",
  "Record the trade in your Journal with entry/exit and rule breaks.": "Registre a operação no Diário com entrada/saída e infrações.",
  "Report periods": "Períodos do relatório",
  "Review overnight action": "Revisar o movimento overnight",
  "Review the full parsed list before committing — deselect anything you don't want (e.g. a scratch trade), then click Import N Trades. The Import History table at the bottom logs every batch with how many rows were imported vs. skipped as duplicates.": "Revise a lista completa antes de confirmar — desmarque o que não quiser (ex.: operação neutra) e clique em Importar N operações. A tabela de histórico registra cada lote com as linhas importadas e as puladas como duplicatas.",
  "Review your edge": "Revise sua vantagem",
  "Review your edge in the Analytics and Edge Lab tabs.": "Revise sua vantagem nas abas Análises e Edge Lab.",
  "Review your performance": "Revise seu desempenho",
  "Review — score the trade 1–10, record the lesson learned, and note one action item for next time": "Revisão — pontue a operação de 1 a 10, registre a lição aprendida e anote uma ação para a próxima vez",
  "Risk configuration": "Configuração de risco",
  "Risk parameters, vocabulary, and account controls.": "Parâmetros de risco, vocabulário e controles de conta.",
  "Rows with fewer than 20 samples are flagged with a ⚠ — don't draw conclusions from small sample sizes. Keep tagging trades consistently to grow confidence in the numbers.": "Linhas com menos de 20 amostras recebem ⚠ — não tire conclusões de amostras pequenas. Continue marcando com consistência para ganhar confiança nos números.",
  "Rule Break": "Infração",
  "Rule breaks": "Infrações",
