  "Set your per-trade risk (% of account), max daily loss ($), max open risk (%), max concurrent trades, and minimum acceptable R. These values appear as reference benchmarks throughout the app — nothing is enforced automatically, they're there to keep you honest.": "Defina risco por operação (% da conta), perda diária máxima ($), risco aberto máximo (%), operações simultâneas máximas e R mínimo aceitável. Esses valores aparecem como referências em todo o app — nada é imposto automaticamente; existem para manter você honesto.",
  "Set your risk parameters": "Defina seus parâmetros de risco",
