  "Supported formats": "Formatos suportados",
  "Supports MT5 \"Trade History Report\" Excel exports, MT4 HTML statements, MT5 XML exports, and CSV files": "Suporta exportações Excel \"Trade History Report\" do MT5, extratos HTML do MT4, XML do MT5 e arquivos CSV",
  "Switch between Daily, Weekly, and Monthly using the segmented control inside the module. The header date range acts as a pre-filter on top of that — set it to YTD to make sure a full year of weekly data is available to summarize.": "Alterne entre Diário, Semanal e Mensal com o controle segmentado do módulo. O período do cabeçalho age como pré-filtro — coloque em YTD para ter um ano inteiro de dados semanais.",
  "TAKEN": "REALIZADA",
  "Tag any discipline violation on a trade (moved stop, oversized position, FOMO entry, etc.) from the Context tab. This surfaces in Analytics so you can measure whether rule-break trades actually underperform clean ones.": "Marque qualquer violação de disciplina (stop movido, posição excessiva, entrada por FOMO etc.) pela aba Contexto. Isso aparece nas Análises para medir se operações com infração rendem menos que as limpas.",
  "Tags represent independent market conditions confirming or contradicting the setup. Most carry weight +1; contrarian tags like Trading Range carry weight −1. The confirmation count is the sum of enabled tag weights, and grade is set manually once you've weighed the full picture.": "As etiquetas representam condições de mercado independentes que confirmam ou contradizem o setup. A maioria pesa +1; etiquetas contrárias como Lateralização pesam −1. A contagem de confirmações é a soma dos pesos ativos, e a nota é atribuída manualmente após pesar o quadro completo.",
  "The Overview shows KPIs (win rate, profit factor, expectancy, total P&L) for the active date range, an equity curve, your active Watchlist items, and recent Journal entries. Everything responds to the date and session filter in the header — these are the same underlying numbers shown on the Analytics page for the same filter.": "A Visão Geral mostra KPIs (taxa de acerto, fator de lucro, expectativa, P&L total) do período ativo, uma curva de equity, seus itens ativos da Watchlist e as entradas recentes do Diário. Tudo responde ao filtro de data e sessão do cabeçalho — são os mesmos números da página Análises para o mesmo filtro.",
  "The Routine module stores your Standard Operating Procedure as a checklist split into Prepare / Execute / Review groups — pre-market prep, intraday rules, and post-market review. Treat it as a living document you refine weekly.": "O módulo Rotina guarda seu procedimento operacional padrão como checklist dividida em Preparar / Executar / Revisar — preparação pré-mercado, regras intradiárias e revisão pós-mercado. Trate-o como um documento vivo refinado semanalmente.",
  "The authoritative record of every trade you have taken.": "O registro oficial de cada operação realizada.",
  "The date range picker and session pills in the top bar filter data across the entire platform, not just this page.": "O seletor de datas e as pílulas de sessão da barra superior filtram os dados de toda a plataforma, não só desta página.",
  "The dominant market regime or macro context driving this setup. Pick the single most important factor (e.g. 'Above VWAP', 'Trend Day', 'Consolidation').": "O regime de mercado ou contexto macro dominante deste setup. Escolha o fator mais importante (ex.: 'Acima do VWAP', 'Dia de tendência', 'Consolidação').",
  "The header date range and session filter apply here exactly as they do on Overview — narrow to a single week to isolate what changed after a bad stretch, or widen to All Time for the full picture. These numbers always match Overview for the same filter.": "O período e o filtro de sessão do cabeçalho valem aqui como na Visão Geral — estreite para uma semana para isolar o que mudou após uma fase ruim, ou amplie para Todo o período. Esses números sempre batem com a Visão Geral para o mesmo filtro.",
  "The market session when the trade was opened. Pre-Market (<9:30), Open (9:30–11:00), Midday (11:00–14:00), Close (14:00–16:00), Post-Market (>16:00). EST.": "A sessão em que a operação foi aberta. Pré-mercado (<9h30), Abertura (9h30–11h), Meio-dia (11h–14h), Fechamento (14h–16h), Pós-mercado (>16h). EST.",
  "The moment a file is parsed, every row is checked against your existing Journal trades by ticker, direction, entry price, and open time. Matches are highlighted amber and auto-deselected in the preview table, so re-uploading the same statement won't create duplicate rows. Use New Only to reset the selection to just the fresh trades, or manually re-check a row to force a re-import.": "Ao analisar um arquivo, cada linha é comparada com suas operações por símbolo, direção, preço de entrada e horário de abertura. Correspondências são destacadas em âmbar e desmarcadas automaticamente — reenviar o mesmo extrato não cria duplicatas. Use Apenas novos para redefinir a seleção, ou remarque uma linha para forçar a reimportação.",
  "The name of the repeatable pattern from your Playbook. Consistent naming lets the Edge Lab group trades by setup for performance analysis.": "O nome do padrão repetível do seu Playbook. Nomes consistentes permitem ao Edge Lab agrupar operações por setup.",
  "The right rail gives one-click shortcuts to the most common actions, plus a live list of your active Playbook setups so you can jump straight into a documented edge.": "A coluna direita traz atalhos de um clique para as ações mais comuns, além de uma lista ao vivo dos seus setups ativos para entrar direto em uma vantagem documentada.",
  "The trade table is a full working data grid, not just a static list.": "A tabela de operações é uma grade de dados completa, não uma lista estática.",
  "This Month": "Este mês",
  "This Week": "Esta semana",
  "Ticker Analysis — total R and P&L per instrument, sorted by P&L": "Análise por símbolo — R total e P&L por instrumento, ordenado por P&L",
  "Ticker dropdown narrows the table to one instrument": "A lista de símbolos restringe a tabela a um instrumento",
  "Ticket": "Ticket",
  "Today": "Hoje",
  "Toggle light/dark mode with the sun/moon button in the top bar. Your preference is saved to your account, so it follows you across devices.": "Alterne claro/escuro com o botão sol/lua da barra superior. Sua preferência é salva na conta e acompanha você entre dispositivos.",
  "Trade Data — edit every field: ticker, direction, session, status, entry/exit price, size, R multiple, P&L, fees, opened/closed timestamps": "Dados — edite cada campo: símbolo, direção, sessão, status, preços de entrada/saída, tamanho, múltiplo R, P&L, taxas, horários de abertura/fechamento",
  "Trade detail — click any row": "Detalhe da operação — clique em qualquer linha",
